UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir cümlede EYLEMİ YAPAN belirsiz, önemsiz veya zaten biliniyorsa edilgen çatı tercih edilir; yapı: [[q]]be (zamana göre çekimlenir) + V3[[/q]] şeklindedir:", "items": [{"heading": "Edilgen Çatının Kullanım Nedeni", "badge": "Ne Zaman Kullanılır", "body": [{"type": "text", "text": "Eylemi yapan [[amber]]belirsiz[[/amber]], [[amber]]önemsiz[[/amber]] ya da zaten biliniyorsa edilgen çatı tercih edilir — İngilizce akademik/haber metinlerinde çok sık görülür, bu yüzden YDS'de boşluk doldurma ve çeviri sorularının klasik konusudur."}]}, {"heading": "\"by + Fail\" Sinyali", "body": [{"type": "text", "text": "Cümlede [[q]]\"by + fail\"[[/q]] (\"by the committee\", \"by scientists\") varsa, EYLEMİ YAPANIN vurgulandığı anlaşılır."}, {"type": "example_check", "correct": "The bridge was built by the committee", "wrong_note": "\"built\" (aktif çatı) özne eylemi kendisi yapıyormuş gibi okutur, bu yüzden yanlıştır"}]}, {"heading": "Çeviri Sorularında Edilgen Sinyali", "body": [{"type": "text", "text": "Türkçe [[amber]]\"-ıl/-in/-ün\"[[/amber]] ekiyle biten fiiller (\"inşa edildi\", \"seçildi\") İngilizce şıklarda [[q]]\"was/were + V3\"[[/q]] arar."}, {"type": "text", "text": "Bu şıklardan aktif çatıda yazılmış olanlar ([[bad]]\"built\"[[/bad]] yerine [[ok]]\"was built\"[[/ok]] olmalıyken sadece [[bad]]\"built\"[[/bad]] yazanlar) hemen elenir."}]}], "examples": [{"sentence": "The new bridge was built by the local government last year.", "answer_word": "was built", "reasoning": "Köprüyü kimin inşa ettiği vurgulanıyor ([[q]]\"by the local government\"[[/q]]) ve özne ([[b]]bridge[[/b]]) eylemi kendisi yapamayacağı için edilgen çatı gerekir → doğru cevap [[right]]\"was built\"[[/right]]tır, [[wrong]]\"built\"[[/wrong]] değil."}, {"sentence": "This novel has been translated into more than twenty languages since its publication.", "answer_word": "has been translated", "reasoning": "Eylemi kimin yaptığı (çevirmenler) önemsiz, önemli olan romanın başına gelen şey → doğru cevap [[right]]\"has been translated\"[[/right]]dır, aktif çatıdaki [[wrong]]\"has translated\"[[/wrong]] yanlıştır çünkü roman çeviri eylemini kendisi yapamaz."}, {"sentence": "Thousands of jobs were lost as a result of the factory closures last year.", "answer_word": "were lost", "reasoning": "Eylemi kimin yaptığı önemsiz, önemli olan işçilerin başına gelen şey olduğu için doğru cevap [[right]]\"were lost\"[[/right]]tur; aktif çatıdaki [[wrong]]\"lost\"[[/wrong]] (özne işleri kendisi kaybetmiş gibi okunur) burada yanlıştır."}, {"sentence": "The ancient manuscript was discovered by archaeologists during a recent excavation in the region.", "answer_word": "was discovered", "reasoning": "Cümlede EYLEMİ YAPAN ([[q]]\"by archaeologists\"[[/q]]) açıkça belirtildiği ve özne ([[b]]manuscript[[/b]]) eylemi kendisi yapamayacağı için doğru cevap [[right]]\"was discovered\"[[/right]]tur, aktif çatıdaki [[wrong]]\"discovered\"[[/wrong]] yanlıştır."}]}$tagbd$::jsonb WHERE id = 'd9e204e0-755b-48a2-9417-55b55e5fa77f';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Phrasal verb'lerde fiil + parçacığın anlamı, tek tek kelimelerin anlamından tamamen [[dark]]BAĞIMSIZDIR[[/dark]] — bu kalıplar parçalarına ayrılmadan [[b]]TEK bir kelime[[/b]] gibi ezberlenmelidir:", "items": [{"heading": "Kelime Kelime Çevirmek Yanıltır", "badge": "Ezberlenecek Kalıplar", "body": [{"type": "text", "text": "[[q]]\"give up\"[[/q]] (vazgeçmek), [[q]]\"look up\"[[/q]] (araştırmak/bulmak), [[q]]\"run out of\"[[/q]] (tükenmek) gibi kalıpları kelime kelime çevirmeye çalışmak yanıltıcıdır; bunlar [[b]]TEK bir kelime[[/b]] gibi ezberlenmelidir."}]}, {"heading": "Sınavlarda İki Soru Tipi", "body": [{"type": "text", "text": "Sınavlarda phrasal verb soruları genellikle İKİ şekilde karşımıza çıkar: (1) boşluğa uygun phrasal verb'ü tamamlama, (2) cümledeki bir phrasal verb'ün ANLAMINI tek kelimelik bir eşanlamlıyla (synonym) değiştirme."}, {"type": "text", "text": "Bu tür sorularda phrasal verb'ü parçalarına ayırıp tahmin etmek yerine, bağlamdaki olayın [[dark]]SONUCUNA[[/dark]] bakıp hangi tek kelimenin (ör. [[q]]\"postpone\"[[/q]], [[q]]\"abandon\"[[/q]], [[q]]\"discover\"[[/q]]) o sonucu ifade ettiğini bulmak gerekir."}]}, {"heading": "Aynı Fiil, Farklı Parçacık = Farklı Anlam", "body": [{"type": "text", "text": "Aynı fiil farklı parçacıklarla [[dark]]TAMAMEN FARKLI[[/dark]] anlamlara gelebilir: [[pair]]give up->vazgeçmek[[/pair]], [[pair]]give in->teslim olmak[[/pair]], [[pair]]give away->ifşa etmek/bağışlamak[[/pair]]."}, {"type": "text", "text": "Bu yüzden parçacığı değiştirip anlamı sabit tutmak büyük bir hatadır."}]}], "examples": [{"sentence": "Due to the heavy snowfall, the flight was put off until further notice.", "answer_word": "put off", "reasoning": "Cümlenin anlamı uçuşun [[b]]ERTELENDİĞİni[[/b]] gösteriyor → doğru cevap [[right]]\"put off\"[[/right]] (ya da [[right]]\"postponed\"[[/right]]) dur; [[wrong]]\"called off\"[[/wrong]] (tamamen iptal etme) ise \"until further notice\" (daha sonra haber verilecek) ifadesiyle çelişir çünkü bu ifade uçuşun İLERİDE gerçekleşeceğini ima eder, tamamen iptali değil."}, {"sentence": "The committee decided to give up on the proposal after months of criticism.", "answer_word": "give up on", "reasoning": "Bağlamda aylar süren eleştiriden SONRA teklifin tamamen [[dark]]TERK EDİLDİĞİ[[/dark]] anlatılıyor → doğru cevap [[right]]\"give up on\"[[/right]] (ya da [[right]]\"abandon/drop\"[[/right]]) dur; [[wrong]]\"give away\"[[/wrong]] (ifşa etmek/bağışlamak) burada anlamsız kaçar çünkü parçacık farklı olduğu için fiilin anlamı tamamen değişmiştir."}, {"sentence": "The negotiations broke down when both sides refused to compromise on the price.", "answer_word": "broke down", "reasoning": "Cümlede tarafların uzlaşmayı REDDETMESİ, görüşmelerin [[dark]]BAŞARISIZLIKLA SONA ERDİĞİNİ[[/dark]] gösteriyor → doğru cevap [[right]]\"broke down\"[[/right]]dır (çökmek/bozulmak); [[wrong]]\"broke up\"[[/wrong]] (ayrılmak, genellikle ilişkiler için) ya da [[wrong]]\"broke out\"[[/wrong]] (aniden başlamak, örn. savaş) parçacık farklı olduğu için tamamen yanlış bir anlam verir."}, {"sentence": "After the scandal, the CEO was forced to step down from his position.", "answer_word": "step down", "reasoning": "Skandaldan sonra bir yöneticinin [[dark]]GÖREVİNİ BIRAKMAYA ZORLANDIĞI[[/dark]] anlatılıyor → doğru cevap [[right]]\"step down\"[[/right]]dır; [[wrong]]\"step up\"[[/wrong]] (bir göreve adım atmak/sorumluluk almak) parçacığın yön zıtlığı yüzünden tam tersi bir anlam taşır ve burada yanlıştır."}]}$tagbd$::jsonb WHERE id = '04b7a35d-06c1-4a16-bab7-0190185e82b0';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]\"on\"[[/q]] parçacığı taşıyan phrasal verb'ler genellikle [[dark]]DEVAM ETME[[/dark]] veya bir cihazı/sistemi [[dark]]ÇALIŞTIRMA[[/dark]] anlamı taşır; [[q]]\"off\"[[/q]] parçacığı taşıyanlar ise genellikle [[dark]]DURDURMA[[/dark]], [[dark]]İPTAL ETME[[/dark]] veya [[dark]]AYRILMA[[/dark]] anlamı taşır:", "items": [{"heading": "\"on\" Parçacığı: Devam Etme / Çalıştırma", "body": [{"type": "text", "text": "[[pair]]go on->devam etmek[[/pair]], [[pair]]carry on->sürdürmek[[/pair]], [[pair]]turn on->açmak[[/pair]], [[pair]]put on->giymek/takmak, üzerine koymak[[/pair]]."}]}, {"heading": "\"off\" Parçacığı: Durdurma / İptal / Ayrılma", "body": [{"type": "text", "text": "[[pair]]turn off->kapatmak[[/pair]], [[pair]]call off->iptal etmek[[/pair]], [[pair]]take off->çıkarmak/kalkış yapmak[[/pair]], [[pair]]set off->yola çıkmak[[/pair]]."}]}, {"heading": "turn on / turn off: Zıt Anlam Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[q]]\"turn on/off\"[[/q]] çifti doğrudan zıt anlamlıdır, bu yüzden bir cihazla ilgili cümlede eylemin başlatma mı durdurma mı olduğuna bakılmalıdır:"}], "meaning_pairs": [[{"word": "turn on", "meaning": "açmak"}, {"word": "turn off", "meaning": "kapatmak", "variant": "wrong"}]], "warning_text": "\"off\" bazen olumsuz bir sonucu ([[q]]\"call off\"[[/q]] = iptal, kötü haber) işaret ederken \"on\" genellikle sürekliliği/olumlu devamı işaret eder."}], "examples": [{"sentence": "Due to the heavy storm, the organizers decided to call off the outdoor concert.", "answer_word": "call off", "reasoning": "Fırtına nedeniyle etkinliğin [[dark]]İPTAL EDİLMESİ[[/dark]] anlatıldığı için doğru cevap [[right]]\"call off\"[[/right]]tur; [[wrong]]\"call on\"[[/wrong]] (birine rica etmek/ziyaret etmek) burada anlamsal olarak uymaz."}, {"sentence": "Despite the technical problems, the committee decided to go on with the meeting as planned.", "answer_word": "go on", "reasoning": "Teknik sorunlara rağmen toplantının [[dark]]DEVAM ETMESİ[[/dark]] anlatıldığı için doğru cevap [[right]]\"go on\"[[/right]] (ya da [[right]]\"carry on\"[[/right]]) dur; [[wrong]]\"go off\"[[/wrong]] (patlamak, bozulmak, çalmak gibi farklı bir anlam taşır) burada cümledeki devam etme fikriyle çelişir."}, {"sentence": "Even though it was freezing outside, he refused to put on his jacket before stepping out the door.", "answer_word": "put on", "reasoning": "Burada bir giysiyi üzerine koyma/giyme eylemi anlatıldığı için doğru cevap [[right]]\"put on\"[[/right]]dur; [[wrong]]\"take off\"[[/wrong]] (çıkarmak) tam ters bir anlam ifade eder ve \"before stepping out\" (dışarı çıkmadan önce) bağlamıyla çelişir."}, {"sentence": "Please remember to turn off all the lights and the air conditioner before leaving the office tonight.", "answer_word": "turn off", "reasoning": "\"lights\" ve \"air conditioner\" birer cihaz olduğu ve cümle bu cihazların [[dark]]DURDURULMASINI/KAPATILMASINI[[/dark]] anlattığı için doğru cevap [[right]]\"turn off\"[[/right]]tur; [[wrong]]\"turn on\"[[/wrong]] (açmak) burada anlam olarak tam tersini ifade eder."}]}$tagbd$::jsonb WHERE id = 'c477b842-983a-4a45-847d-1d7db0d30e83';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]\"up\"[[/q]] parçacığı taşıyan phrasal verb'ler genellikle [[dark]]ARTIŞ[[/dark]], [[dark]]TAMAMLANMA[[/dark]] veya [[dark]]ORTAYA ÇIKMA[[/dark]] anlamı taşır; [[q]]\"down\"[[/q]] parçacığı taşıyanlar ise genellikle [[dark]]AZALMA[[/dark]], [[dark]]DURMA[[/dark]] veya [[dark]]KAYDETME[[/dark]] anlamı taşır:", "items": [{"heading": "\"up\" Parçacığı: Artış / Tamamlanma / Ortaya Çıkma", "body": [{"type": "text", "text": "[[pair]]pick up->toplamak, artırmak[[/pair]], [[pair]]show up->ortaya çıkmak, gelmek[[/pair]], [[pair]]end up->sonunda bir duruma gelmek[[/pair]], [[pair]]give up->vazgeçmek[[/pair]] (burada \"up\" tamamlanma/bitirme anlamı taşır)."}]}, {"heading": "\"down\" Parçacığı: Azalma / Durma / Kaydetme", "body": [{"type": "text", "text": "[[pair]]slow down->yavaşlamak[[/pair]], [[pair]]break down->bozulmak, arızalanmak[[/pair]], [[pair]]write down->not almak, kaydetmek[[/pair]], [[pair]]let down->hayal kırıklığına uğratmak[[/pair]]."}]}, {"heading": "break down / break up: Benzer Görünen Tuzak", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[q]]\"break down\"[[/q]] ile [[q]]\"break up\"[[/q]] birbirine çok benzer görünür ama farklı öznelerle kullanılır:"}], "meaning_pairs": [[{"word": "break down", "meaning": "bozulmak / arızalanmak (cihaz, sistem, resmi görüşme)"}, {"word": "break up", "meaning": "dağılmak (ilişki, grup)", "variant": "wrong"}]], "warning_text": "Bağlamdaki ÖZNEYE bakmak (cihaz/sistem mi, ilişki/grup mu) doğru parçacığı seçmenin anahtarıdır."}], "examples": [{"sentence": "After waiting for an hour, we realized he wasn't going to show up, so we left without him.", "answer_word": "show up", "reasoning": "Beklenen kişinin gelmemesi/ortaya çıkmaması anlatıldığı için doğru cevap [[right]]\"show up\"[[/right]]tır; [[wrong]]\"show off\"[[/wrong]] (hava atmak, caka satmak) burada anlamsal olarak hiç uymaz."}, {"sentence": "The old printer kept breaking down every few minutes, so we had to call a technician.", "answer_word": "breaking down", "reasoning": "Eski yazıcının sürekli [[dark]]ARIZALANMASI[[/dark]] anlatıldığı için doğru cevap [[right]]\"breaking down\"[[/right]]dır; [[wrong]]\"breaking up\"[[/wrong]] burada bir cihaz için değil, genellikle bir ilişkinin/grubun dağılması için kullanıldığından bağlama uymaz."}, {"sentence": "She has decided to give up her job to focus on her new business, even though it pays less.", "answer_word": "give up", "reasoning": "Burada bir işten vazgeçme anlamı olduğu için doğru cevap [[right]]\"give up\"[[/right]]tır (tamamlama/bitirme anlamı taşıyan \"up\"); [[bad]]\"give down\"[[/bad]] diye bir ifade yoktur."}, {"sentence": "Please write down your phone number so I don't forget it.", "answer_word": "write down", "reasoning": "Burada bir bilgiyi not alma anlamı olduğu için doğru cevap [[right]]\"write down\"[[/right]]dır (kaydetme anlamı taşıyan \"down\"); [[wrong]]\"write up\"[[/wrong]] farklı bir anlam taşır (resmi rapor hazırlamak), bu basit not alma eylemine uymaz."}]}$tagbd$::jsonb WHERE id = '24970b9d-ad2c-46a4-b57c-96942eaa01e7';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Sahip olan varlık [[dark]]CANLI[[/dark]] (insan, hayvan) ya da örgütlü bir [[dark]]GRUP/KURUM[[/dark]] ise iyelik [[q]]'s[[/q]] tercih edilir; sahip olan [[dark]]CANSIZ[[/dark]] bir nesne ya da soyut bir kavramsa genellikle [[q]]\"of\"[[/q]] yapısı tercih edilir:", "items": [{"heading": "Canlı/Kurum mu, Cansız mı?", "badge": "'s / of Seçimi", "sub_rules": [{"condition": "[[amber]]İnsan, hayvan veya kurum/grup[[/amber]] sahipse [[b]]'s[[/b]] kullanılır:", "from": "the company", "to": "the company's profits"}, {"condition": "[[amber]]Cansız nesne veya soyut kavram[[/amber]] sahipse genellikle [[b]]\"of\"[[/b]] tercih edilir:", "from": "the building's roof", "to": "the roof of the building"}, {"condition": "[[amber]]Zaman ifadeleri[[/amber]] CANSIZ olsa da istisna olarak [[b]]'s[[/b]] alır:", "from": "the newspaper of today", "to": "today's newspaper"}]}, {"heading": "Çoklu Sahiplikte Tek 's Kuralı", "body": [{"type": "text", "text": "Birden fazla isim art arda ORTAK bir şeye sahipse en sona SADECE BİR [[q]]'s[[/q]] eklenir; her isim AYRI AYRI sahiplik belirtiyorsa her isme kendi [[q]]'s[[/q]]'i eklenir."}, {"type": "example_check", "correct": "my sister and brother's car", "wrong_note": "bu, ortak TEK bir arabaya işaret eder; ayrı arabalar için \"my sister's and brother's cars\" gerekir"}]}], "examples": [{"sentence": "The main entrance of the museum was closed for renovation, so visitors had to use the side door.", "answer_word": "The main entrance of the museum", "reasoning": "Sahip olan şey (müze binası) [[dark]]CANSIZ[[/dark]] bir yapı olduğu için doğru cevap [[right]]\"The main entrance of the museum\"[[/right]] şeklindeki \"of\" yapısıdır; [[wrong]]\"The museum's\"[[/wrong]] burada tercih edilen seçenek değildir."}, {"sentence": "The company's latest financial report revealed a significant increase in annual revenue.", "answer_word": "The company's", "reasoning": "Sahip olan burada bir [[dark]]KURUM[[/dark]] (the company) olduğu için doğru cevap [[right]]\"The company's\"[[/right]]tir; kurumlar/canlı örgütler için 's kullanımı doğaldır, \"of the company\" da gramer olarak doğru olsa da sınavda 's seçeneği bu bağlamda önceliklidir."}, {"sentence": "Today's newspaper contained an in-depth analysis of the election results.", "answer_word": "Today's", "reasoning": "\"today\" bir [[dark]]ZAMAN İFADESİ[[/dark]] olduğu için CANSIZ olmasına rağmen istisnai olarak 's kullanılır → doğru cevap [[right]]\"Today's\"[[/right]]tir; [[wrong]]\"The newspaper of today\"[[/wrong]] gramer olarak doğru olsa da zaman ifadelerinde doğal ve beklenen tercih 's'dir."}, {"sentence": "My manager's and my colleague's opinions on the matter were surprisingly similar, even though they work in different departments.", "answer_word": "My manager's and my colleague's", "reasoning": "Burada iki kişinin [[dark]]AYRI AYRI[[/dark]] görüşlerinden bahsedildiği (\"different departments\" ayrımı) için her isme kendi 's'i eklenir → doğru cevap [[right]]\"My manager's and my colleague's\"[[/right]]tir; sadece sona tek bir 's eklemek ([[wrong]]\"my manager and colleague's\"[[/wrong]]) burada yanlış olur çünkü bu TEK bir ORTAK görüşe işaret eder, oysa burada ayrı görüşler karşılaştırılıyor."}]}$tagbd$::jsonb WHERE id = '80ed5209-f8ab-4520-a652-d047080314b7';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Past Perfect Continuous ([[q]]had been + V-ing[[/q]]), geçmişte belirli bir ANDAN ÖNCE BAŞLAYIP O ANA KADAR DEVAM ETMİŞ bir eylemin SÜRESİNİ vurgulamak için kullanılır:", "items": [{"heading": "Süre Vurgusu: for / since + Ani Olay", "body": [{"type": "text", "text": "Cümlede genellikle [[q]]\"for + süre\"[[/q]] veya [[q]]\"since + başlangıç noktası\"[[/q]] ifadesi ve bu sürenin SONUNDA gerçekleşen başka bir geçmiş olay (past simple) birlikte bulunur."}]}, {"heading": "Süreç mi, Sonuç mu? Düz Past Perfect Farkı", "body": [{"type": "text", "text": "Sadece bir eylemin diğerinden ÖNCE [[dark]]TAMAMLANMIŞ OLMASI[[/dark]] (süreç değil, sonuç) vurgulanıyorsa düz Past Perfect ([[q]]had + V3[[/q]]) yeterlidir."}, {"type": "example_check", "correct": "the flames had destroyed most of the building", "wrong_note": "\"had been destroying\" burada yanlıştır çünkü yangının binayı yok etmiş olması bir SONUÇtur, süren bir eylem değil"}]}], "examples": [{"sentence": "She had been studying for six hours when her computer suddenly crashed.", "answer_word": "had been studying", "reasoning": "\"for six hours\" süre ifadesi ve bu sürenin SONUNDA gerçekleşen ani bir olay ([[q]]\"crashed\"[[/q]]) birlikte kullanıldığı için → doğru cevap [[right]]\"had been studying\"[[/right]]dir."}, {"sentence": "By the time the fire department arrived, the flames had destroyed most of the building.", "answer_word": "had destroyed", "reasoning": "Burada bir süreç değil, bir olayın başka bir olaydan ÖNCE TAMAMLANMIŞ OLMASI (sonuç) vurgulanıyor → doğru cevap [[right]]\"had destroyed\"[[/right]]tür, [[wrong]]\"had been destroying\"[[/wrong]] değildir çünkü yangının binayı yok etmiş olması bir sonuçtur, süren bir eylem değil."}, {"sentence": "The negotiators had been arguing for nearly four hours before they finally reached an agreement just before midnight.", "answer_word": "had been arguing", "reasoning": "\"for nearly four hours\" süre ifadesi ve bu sürenin SONUNDA gerçekleşen bir olay ([[q]]\"reached an agreement\"[[/q]]) birlikte kullanıldığı için doğru cevap [[right]]\"had been arguing\"[[/right]]dir."}, {"sentence": "By the time the ambulance arrived, the paramedics realized that the patient had lost a significant amount of blood.", "answer_word": "had lost", "reasoning": "Burada bir süreç değil, bir olayın ÖNCESİNDE tamamlanmış bir SONUÇ (kan kaybı miktarı) vurgulanıyor ve bir \"for/since\" süre ifadesi yok → doğru cevap düz Past Perfect [[right]]\"had lost\"[[/right]]tur, [[wrong]]\"had been losing\"[[/wrong]] değildir çünkü vurgulanan süren bir eylem değil, ulaşılmış bir sonuçtur."}]}$tagbd$::jsonb WHERE id = 'ff149e71-23ef-4074-841c-77fb2ad004f8';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir cümlede İKİ farklı geçmiş zaman eylemi varsa ve bunlardan biri DİĞERİNDEN ÖNCE gerçekleşmişse, daha ÖNCE olan eylem [[q]]had + V3[[/q]] (Past Perfect), daha SONRA olan ise Past Simple ile anlatılır:", "items": [{"heading": "Sıralama Sinyalleri", "body": [{"type": "text", "text": "Cümlede [[q]]\"before\"[[/q]], [[q]]\"after\"[[/q]], [[q]]\"by the time\"[[/q]], [[q]]\"already\"[[/q]], [[q]]\"when\"[[/q]] gibi sıralama belirten kelimeler varsa, bu kelimelere bakarak hangi eylemin önce olduğunu belirle: \"before/by the time X happened\" ifadesinden önce yaşanan eylem [[q]]had + V3[[/q]] alır."}]}, {"heading": "Ard Arda Olaylarda Past Perfect Gerekmez", "body": [{"type": "text", "text": "İki eylem AYNI ANDA veya ART ARDA (önce-sonra ayrımı olmadan) gerçekleşiyorsa her ikisi de Past Simple kalır, Past Perfect kullanmaya gerek yoktur."}, {"type": "example_check", "correct": "I bought a ticket and boarded the train", "wrong_note": "burada eylemler ART ARDA gerçekleştiği için Past Perfect gerekmez, düz Past Simple yeterlidir"}]}], "examples": [{"sentence": "When I arrived at the station, the train had already left.", "answer_word": "had already left", "reasoning": "Trenin benim varışımdan ÖNCE kalkmış olması gerekiyor → doğru cevap [[right]]\"had already left\"[[/right]]tir."}, {"sentence": "When I arrived at the station, I bought a ticket and boarded the train.", "answer_word": "bought a ticket and boarded", "reasoning": "Burada biletin alınması ve trene binilmesi varıştan SONRA, ART ARDA gerçekleşen eylemler → doğru cevap düz Past Simple'dır ([[right]]\"bought... boarded\"[[/right]]), Past Perfect gerekmez çünkü bu eylemler varıştan önce değil sonra olmuştur."}, {"sentence": "By the time the ambulance arrived, the injured man had regained consciousness.", "answer_word": "had regained", "reasoning": "Bilincin geri kazanılması ambulansın varışından ÖNCE gerçekleştiği için doğru cevap [[right]]\"had regained\"[[/right]]tır."}, {"sentence": "As soon as she finished her exam, she rushed outside to call her mother.", "answer_word": "finished", "reasoning": "İki eylem ART ARDA, sınavın bitmesinin HEMEN SONRASINDA gerçekleştiği için doğru cevap düz Past Simple'dır ([[right]]\"finished\"[[/right]]), Past Perfect gerekmez çünkü sınavın bitmesi sınav bitmeden önce olan bir olay değil, dışarı koşmadan hemen önceki ardışık bir olaydır."}]}$tagbd$::jsonb WHERE id = 'a135dd9a-ca92-4a2a-ba36-92fd33040149';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Yer edatı seçerken ismin TÜRÜNE bak: isim bir NOKTA/konum olarak düşünülüyorsa [[q]]\"at\"[[/q]], bir YÜZEY ise [[q]]\"on\"[[/q]], bir HACİM/ALAN içindeyse [[q]]\"in\"[[/q]] kullanılır:", "items": [{"heading": "Nokta / Yüzey / Hacim", "badge": "at / on / in Seçimi", "sub_rules": [{"condition": "İsim bir [[amber]]NOKTA/konum[[/amber]] olarak düşünülüyorsa:", "from": "the bus stop", "to": "at the bus stop"}, {"condition": "İsim bir [[amber]]YÜZEY[[/amber]] ise:", "from": "the table", "to": "on the table"}, {"condition": "İsim bir [[amber]]HACİM/ALAN[[/amber]] içindeyse:", "from": "the room", "to": "in the room"}]}, {"heading": "Aynı Kelime, Farklı Bağlam", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Aynı kelime bağlama göre farklı edat alabilir; YDS bu ince farkı sıkça kullanır:"}], "meaning_pairs": [[{"word": "at school", "meaning": "okulda (genel bir eğitim faaliyeti olarak)"}, {"word": "in the school", "meaning": "okul binasının fiziksel içinde", "variant": "wrong"}], [{"word": "at the corner of the street", "meaning": "sokağın köşesinde (dışarıdan, açık alan)"}, {"word": "in the corner of the room", "meaning": "odanın köşesinde (kapalı alan içinde)", "variant": "wrong"}]], "warning_text": "Cümledeki mekanın NOKTA/YÜZEY/HACİM niteliğine bakmadan ezbere edat seçmek yanlış sonuca götürür."}], "examples": [{"sentence": "She was waiting at the bus stop when it started to rain.", "answer_word": "at", "reasoning": "Otobüs durağı bir [[dark]]NOKTA/konum[[/dark]] olarak düşünüldüğü için doğru cevap [[right]]\"at\"[[/right]]tır; [[wrong]]\"in\"[[/wrong]] veya [[wrong]]\"on\"[[/wrong]] burada yanlıştır."}, {"sentence": "The committee placed a small plaque on the wall to commemorate the founder.", "answer_word": "on", "reasoning": "Duvar bir [[dark]]YÜZEY[[/dark]] olduğu için doğru cevap [[right]]\"on\"[[/right]]dur; aynı cümlede \"the room\" kullanılsaydı (kapalı bir hacim), doğru edat [[wrong]]\"in\"[[/wrong]] olurdu."}, {"sentence": "A mysterious stain had appeared on the ceiling of the old library.", "answer_word": "on", "reasoning": "Tavan bir [[dark]]YÜZEY[[/dark]] olarak düşünüldüğü için doğru cevap [[right]]\"on\"[[/right]]dur; [[wrong]]\"in\"[[/wrong]] ya da [[wrong]]\"at\"[[/wrong]] burada yanlıştır."}, {"sentence": "The peace treaty was signed in Geneva in the presence of several world leaders.", "answer_word": "in", "reasoning": "Geneva bir şehir, yani bir [[dark]]HACİM/ALAN[[/dark]] olarak düşünüldüğü için doğru cevap [[right]]\"in\"[[/right]]dir; [[wrong]]\"at\"[[/wrong]] kullanılsaydı şehir genel bir alan değil belirli tek bir nokta olarak ele alınırdı."}]}$tagbd$::jsonb WHERE id = 'cc4e9127-c8fe-44d1-b098-711c0e2c2432';
